//--------------------------------------------------------------------------//

void tr_timeout( void )
{
    if( tr_lock_status && tr_status  )
    {
        ATOMIC(tr_status=FALSE);
        
        if( tr_oem )
        {
            ATOMIC( tr_oem = FALSE ) ;

            timeout_q_remove((Timeout_Q_Func)tr_car_rearm ) ;
            timeout_q_insert((Timeout_Q_Func)tr_car_rearm , NULL , TR_REARM_TIMEOUT , 1 , 1);         
            
        }
        
        timeout_q_remove( (Timeout_Q_Func)tr_car_relock );
        timeout_q_insert( (Timeout_Q_Func)tr_car_relock , NULL,TR_RELOCK_TIMEOUT , 1 , 1 );         
    }
}
        
//--------------------------------------------------------------------------//

void tr_car_rearm( void )
{
    if( tr_lock_status )
    {
        cmd_q_insert( INPUT_OEM_LOCK , 100) ;

        TRACE("\n\r[TR_RS_ARM]\n\r");
    }
}

//--------------------------------------------------------------------------//
    
void tr_car_relock(void)
{    
    if( tr_lock_status )
    {
        cmd_q_insert( INPUT_LOCK1 | INPUT_ON    , 100) ;   

        TRACE("\n\r[TR_RELOCK]\n\r");
    }
}        

